 src=Path(v['file']).read_text();t=ast.parse(src);compile(t,v['file'],'exec')
 assert hashlib.sha256(src.encode()).hexdigest()==p['artifact_hashes'][v['file']]
 cfg=ast.literal_eval(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets)))
 assert cfg==v['config']
 for n in ast.walk(t):
  if isinstance(n,ast.Import): assert all(x.name.split('.')[0] in allowed for x in n.names)
  elif isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
  elif isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__'}

