 old=ast.parse(Path(oldfile).read_text());new=ast.parse(Path('membership_'+mode+'_balanced.py').read_text())
 def methods(t):return {n.name:n for c in t.body if isinstance(c,ast.ClassDef) and c.name=='Model' for n in c.body if isinstance(n,ast.FunctionDef)}
 a,b=methods(old),methods(new)
 assert set(b)-set(a)=={'_balance_feedback_weights'}
 for name,node in a.items():
  newer=b[name]
  if name=='__init__':
   j=next(i for i,v in enumerate(newer.args.args) if v.arg=='membership_weighting')
   num_required=len(newer.args.args)-len(newer.args.defaults)
   newer.args.args.pop(j);newer.args.defaults.pop(j-num_required)
   def newstmt(n):
    if isinstance(n,ast.If) and 'membership_weighting' in ast.unparse(n.test):return True
    return isinstance(n,ast.Assign) and any(isinstance(x,ast.Attribute) and x.attr=='membership_weighting' for x in n.targets)
   newer.body=[n for n in newer.body if not newstmt(n)]
  elif name in ('_compress_both','_compress_with_match','_compress_unique_support'):
   assert isinstance(newer.body[-2],ast.Assign)
   assert ast.unparse(newer.body[-2])=='counts = self._balance_feedback_weights(counts)'
   newer.body.pop(-2)
  assert ast.dump(node,include_attributes=False)==ast.dump(newer,include_attributes=False),(mode,name)
 # Entire inherited surrogate geometry and joint loss source is unchanged.
 funcs=lambda t:{n.name:ast.dump(n,include_attributes=False) for n in t.body if isinstance(n,(ast.FunctionDef,ast.ClassDef)) and n.name"'!='"'Model'}
 assert funcs(old)==funcs(new)

cases=0
for n in range(11):
 for member in range(n+1):
  c=[n-member,member];occupied=[int(x>0) for x in c];k=sum(occupied)
